 if(name.includes('Vendor Management'))return <>{header}<div className="detail-list"><div><strong>Fresh Foods Ltd</strong><span>Score 92 · 27 active rates</span><b className="status active">Approved</b></div><div><strong>Prime Poultry</strong><span>Score 86 · quotation expires in 7 days</span><b className="status near-expiry">Expiring</b></div><div><strong>Dhaka Dairy Co.</strong><span>Score 89 · 1 quotation waiting</span><b className="status pending-approval">Review</b></div></div><button className="btn primary full" onClick={()=>toast('Vendor onboarding checklist opened')}>+ Onboard vendor</button></>
 if(name.includes('BOM')||name.includes('Recipe'))return <>{header}<div className="recipe-preview"><div><strong>Chicken Burger · v4</strong><span>Finished · shelf life 1 day</span></div>{[['Chicken patty','1 pcs','৳60'],['Brioche bun','1 pcs','৳20'],['Burger sauce','0.028 kg','৳11'],['Packaging','1 set','৳5']].map(r=><div key={r[0]}><span>{r[0]}</span><b>{r[1]}</b><em>{r[2]}</em></div>)}<footer><strong>Recipe cost</strong><b>৳96 · 32.0% food cost</b></footer></div><div className="validation good">✓ Shelf life valid · no circular dependency · UOMs match</div><button className="btn primary full" onClick={()=>toast('CSV/XLSX recipe validation preview opened')}>Import recipe file</button></>
